	/**
	 * M7 decline-reason prefix fix: the pattern/VALUES lowering sites are SHARED between the row builder (prefix
	 * {@code ""}) and the aggregate builder (prefix {@code "agg:"}), but historically recorded bare strings — an
	 * aggregate decline surfaced as {@code irKernel:pattern-guards} and the census mis-attributed it as a row-tier
	 * decline. A bind-constant subject refuses both the adjacency guards and the scan fallback, so the shape declines
	 * at exactly such a shared site.
	 */
	@Test
	void aggregateProducerDeclinesCarryTheAggPrefixAtSharedSites() {
		MultiJoinPlan plan = new MultiJoinPlan(
				new SlotPlan[] { pattern(Term.constantSlot(0, 42L), Term.slot(1)),
						pattern(Term.slot(1), Term.slot(2)) },
				new MaskedFilter[0]);
		String previousBridge = System.getProperty(LmdbNativeKernelLowering.PLAN_BRIDGE_PROPERTY);
		System.setProperty(LmdbNativeKernelLowering.PLAN_BRIDGE_PROPERTY, "false");
		try {
			SingletonSet target = new SingletonSet();
			target.setRuntimeTelemetryEnabled(true);
			assertNull(LmdbNativeKernelLowering.lowerAggregate(plan, freshRow(), new int[0],
					new AggregateSpec[] { AggregateSpec.slot("count", 2, false, AggKind.COUNT) }, target));
			assertEquals("irKernel:agg:pattern-guards",
					LmdbNativeAttemptMetrics.dispatchTrace(target).declineReasons(),
					"an aggregate-path decline at a shared lowering site must carry the agg: prefix");
		} finally {
			restoreProperty(LmdbNativeKernelLowering.PLAN_BRIDGE_PROPERTY, previousBridge);
		}
	}

	/**
	 * The corpus's dominant declining shape, {@code Join(pattern, Extension(copies, MultiJoin(pattern)))}. A binary
	 * {@code JoinPlan} exists precisely because an operand is not flattenable, so this asserts the construction too —
	 * if {@code SlotPlan.join} ever flattened an extension, the test would silently stop covering the JoinPlan path.
	 */
	@Test
	void aggregateRungLowersABinaryJoinCoreWithAPureBindAlias() {
		SlotPlan left = pattern(Term.slot(0), Term.slot(1));
		SlotPlan inner = new MultiJoinPlan(new SlotPlan[] { pattern(Term.slot(1), Term.slot(2)) },
				new MaskedFilter[0]);
		SlotPlan right = new ExtensionPlan(inner, new CopyBinding[] { CopyBinding.slot(3, 2) });
		SlotPlan core = SlotPlan.join(left, right);
		assertTrue(core instanceof JoinPlan, "an ExtensionPlan operand must keep the join binary: " + core.getClass());

		// Counting the alias target proves the BindAlias column is a first-class column downstream.
		LmdbNativeKernelLowering.Lowered lowered = lowerCounting(core, 3);
		assertNotNull(lowered, "a binary join whose extension is a pure alias must lower");
		String key = lowered.kernel.shapeKey();
		assertTrue(key.contains("ba(v"), "the alias must lower to a BindAlias over the source column; key=" + key);
		// Both patterns must still be producers: the join descent must not drop an operand.
		assertEquals(2, lowered.bindings.adjacencies.length, "both patterns lower to adjacency requests; key=" + key);
	}

	/** A constant alias, {@code BIND(<c> AS ?d)}, resolves to a constant operand rather than a column. */
	@Test
	void aggregateRungLowersAConstantBindAlias() {
		SlotPlan inner = new MultiJoinPlan(new SlotPlan[] { pattern(Term.slot(0), Term.slot(1)) },
				new MaskedFilter[0]);
		SlotPlan core = SlotPlan.join(pattern(Term.slot(1), Term.slot(2)),
				new ExtensionPlan(inner, new CopyBinding[] { CopyBinding.constant(3, PRED) }));
		LmdbNativeKernelLowering.Lowered lowered = lowerCounting(core, 3);
		assertNotNull(lowered, "a constant alias must lower");
		assertTrue(lowered.kernel.shapeKey().contains("ba(c"), lowered.kernel.shapeKey());
	}

	/**
	 * Computed BINDs lower through {@code hooks.computeBind} since the M7 bind-hook seam. Three boundaries pinned here:
	 * a zero-input repeatable expression folds at lowering time into a constant alias (no per-row hook), an
	 * input-bearing expression registers a bind hook carrying its argument slots, and a non-repeatable expression
	 * (RAND-family) still declines because a re-runnable kernel cannot promise one evaluation per solution.
	 */
	@Test
	void aggregateRungLowersAComputedBindThroughTheBindHookSeam() {
		LmdbNativeCompiledInlineId constant = new LmdbNativeCompiledInlineId(0L, true, row -> PRED);
		LmdbNativeKernelLowering.Lowered folded = lowerCounting(computedBindCore(constant), 2);
		assertNotNull(folded, "a zero-input repeatable expression must fold into a constant alias");
		assertEquals(0, folded.bindings.bindHooks.length, "a folded constant must not register a bind hook");

		LmdbNativeCompiledInlineId dependent = new LmdbNativeCompiledInlineId(1L << 1, true, row -> row.id(1));
		LmdbNativeKernelLowering.Lowered hooked = lowerCounting(computedBindCore(dependent), 2);
		assertNotNull(hooked, "an input-bearing computed BIND must lower through the bind hook");
		assertEquals(1, hooked.bindings.bindHooks.length, "one computed copy registers exactly one bind hook");
		assertArrayEquals(new int[] { 1 }, hooked.bindings.bindHooks[0].argSlots);

		LmdbNativeCompiledInlineId unstable = new LmdbNativeCompiledInlineId(0L, false, row -> PRED);
		assertNull(lowerCounting(computedBindCore(unstable), 2),
				"a non-repeatable expression must keep declining");
	}

	/** The kill switch restores the pre-M7 decline unchanged. */
	@Test
	void bindHookFlagOffRestoresTheComputedBindDecline() {
		System.setProperty(LmdbNativeKernelLowering.BIND_HOOK_PROPERTY, "false");
		try {
			LmdbNativeCompiledInlineId computed = new LmdbNativeCompiledInlineId(0L, true, row -> PRED);
			assertNull(lowerCounting(computedBindCore(computed), 2),
					"flag off must keep computed BINDs out of the kernel");
		} finally {
			System.clearProperty(LmdbNativeKernelLowering.BIND_HOOK_PROPERTY);
		}
	}

	private static SlotPlan computedBindCore(LmdbNativeCompiledInlineId computed) {
		SlotPlan inner = new MultiJoinPlan(new SlotPlan[] { pattern(Term.slot(0), Term.slot(1)) },
				new MaskedFilter[0]);
		return SlotPlan.join(pattern(Term.slot(1), Term.slot(2)),
				new ExtensionPlan(inner, new CopyBinding[] { CopyBinding.computed(3, computed) }));
	}

	// ------------------------------------------------------------------
	// UnionPlan operands (census 2026-07-25)
	// ------------------------------------------------------------------

	/**
	 * {@code ?a PRED ?b . { ?b PRED ?c } UNION { ?b PRED2 ?c }} — both branches bind the same fresh variable, which is
	 * the shape that must share one column. A UnionPlan is never flattenable, so it arrives as a binary JoinPlan
	 * operand.
	 */
	/**
	 * Union lowering is behind a flag that defaults OFF, so every test here sets it explicitly. A test that leaned on
	 * the ambient default would start failing the day the default moves while saying nothing about the behaviour it
	 * protects.
	 */
	private static LmdbNativeKernelLowering.Lowered lowerCountingWithUnions(SlotPlan core, int countedSlot) {
		return lowerAggregateWithUnions(core, countedSlot, false);
	}

	private static LmdbNativeKernelLowering.Lowered lowerDistinctCountingWithUnions(SlotPlan core, int countedSlot) {
		return lowerAggregateWithUnions(core, countedSlot, true);
	}

	private static LmdbNativeKernelLowering.Lowered lowerAggregateWithUnions(SlotPlan core, int countedSlot,
			boolean distinct) {
		String previous = System.getProperty(LmdbNativeKernelLowering.UNION_SOURCES_PROPERTY);
		System.setProperty(LmdbNativeKernelLowering.UNION_SOURCES_PROPERTY, "true");
		try {
			return LmdbNativeKernelLowering.lowerAggregate(core, freshRow(), new int[0],
					new AggregateSpec[] { AggregateSpec.slot("count", countedSlot, distinct, AggKind.COUNT) }, null);
		} finally {
			if (previous == null) {
				System.clearProperty(LmdbNativeKernelLowering.UNION_SOURCES_PROPERTY);
			} else {
				System.setProperty(LmdbNativeKernelLowering.UNION_SOURCES_PROPERTY, previous);
			}
		}
	}

	/** With the flag off a union operand still declines, so the default production path is unchanged. */
	@Test
	void unionOperandDeclinesWhileUnionSourcesAreOff() {
		SlotPlan union = new UnionPlan(pattern(Term.slot(1), Term.slot(2)), pattern(Term.slot(1), Term.slot(2)));
		SlotPlan core = SlotPlan.join(pattern(Term.slot(0), Term.slot(1)), union);
		String previous = System.getProperty(LmdbNativeKernelLowering.UNION_SOURCES_PROPERTY);
		System.setProperty(LmdbNativeKernelLowering.UNION_SOURCES_PROPERTY, "false");
		try {
			assertNull(lowerCounting(core, 2), "union lowering must stay off by default");
		} finally {
			if (previous == null) {
				System.clearProperty(LmdbNativeKernelLowering.UNION_SOURCES_PROPERTY);
			} else {
				System.setProperty(LmdbNativeKernelLowering.UNION_SOURCES_PROPERTY, previous);
			}
		}
	}

	/**
	 * {@code A UNION B UNION C} arrives as {@code UnionPlan(UnionPlan(a,b), c)}. The inner Union must land on a depth
	 * the outer harvest collects, or the outer branch reads as empty and the whole union declines.
	 */
	@Test
	void nestedUnionsLowerToNestedUnionNodes() {
		SlotPlan inner = new UnionPlan(pattern(Term.slot(1), Term.slot(2)), pattern(Term.slot(1), Term.slot(2)));
		SlotPlan outer = new UnionPlan(inner, pattern(Term.slot(1), Term.slot(2)));
		SlotPlan core = SlotPlan.join(pattern(Term.slot(0), Term.slot(1)), outer);
		LmdbNativeKernelLowering.Lowered lowered = lowerCountingWithUnions(core, 2);
		assertNotNull(lowered, "a nested union must lower, not read as an empty branch");
		String key = lowered.kernel.shapeKey();
		assertEquals(2, key.split("u\\{", -1).length - 1, "two Union nodes must appear; key=" + key);
	}

	/**
	 * The other nesting order, {@code Union(a, Union(b, c))} from {@code {A} UNION {{B} UNION {C}}}. This is the order
	 * that catches a per-union pin frame being cleared rather than restored: the outer still has to read its first
	 * branch's pinned columns after the inner union has finished.
	 */
	@Test
	void aUnionNestedInTheSecondBranchAlsoLowers() {
		SlotPlan inner = new UnionPlan(pattern(Term.slot(1), Term.slot(2)), pattern(Term.slot(1), Term.slot(2)));
		SlotPlan outer = new UnionPlan(pattern(Term.slot(1), Term.slot(2)), inner);
		SlotPlan core = SlotPlan.join(pattern(Term.slot(0), Term.slot(1)), outer);
		LmdbNativeKernelLowering.Lowered lowered = lowerCountingWithUnions(core, 2);
		assertNotNull(lowered, "a union nested in the second branch must lower");
		int slot2Columns = 0;
		for (int engineSlot : lowered.bindings.columnEngineSlots) {
			if (engineSlot == 2) {
				slot2Columns++;
			}
		}
		assertEquals(1, slot2Columns, "all three branches share one column for slot 2; columns="
				+ java.util.Arrays.toString(lowered.bindings.columnEngineSlots));
	}

	@Test
	void aggregateRungLowersAUnionOperandToAUnionNode() {
		SlotPlan anchor = pattern(Term.slot(0), Term.slot(1));
		SlotPlan union = new UnionPlan(pattern(Term.slot(1), Term.slot(2)), pattern(Term.slot(1), Term.slot(2)));
		SlotPlan core = SlotPlan.join(anchor, union);
		assertTrue(core instanceof JoinPlan, "a UnionPlan operand must keep the join binary: " + core.getClass());

		LmdbNativeKernelLowering.Lowered lowered = lowerCountingWithUnions(core, 2);
		assertNotNull(lowered, "a union of two lowerable branches must lower");
		String key = lowered.kernel.shapeKey();
		assertTrue(key.contains("u{"), "the union must lower to a Union node; key=" + key);
	}

	@Test
	void distinctColumnProducedByDomainThenProbeAcrossUnionIsNotGloballyOrdered() {
		SlotPlan union = new UnionPlan(classExtent(0, 17L), correlatedProducer(3, 0, 18L));

		LmdbNativeKernelLowering.Lowered lowered = lowerDistinctCountingWithUnions(union, 0);

		assertNotNull(lowered);
		assertEquals(-1, aggregateOutput(lowered).orderedDomain,
				"the second branch rewrites the shared column from an adjacency probe");
	}

	@Test
	void distinctColumnProducedByProbeThenDomainAcrossUnionIsNotGloballyOrdered() {
		SlotPlan union = new UnionPlan(correlatedProducer(3, 0, 18L), classExtent(0, 17L));

		LmdbNativeKernelLowering.Lowered lowered = lowerDistinctCountingWithUnions(union, 0);

		assertNotNull(lowered);
		assertEquals(-1, aggregateOutput(lowered).orderedDomain,
				"an ordered second branch cannot make the preceding probe output ordered");
	}

	@Test
	void nestedUnionDoesNotRestoreSharedColumnOrdering() {
		SlotPlan inner = new UnionPlan(classExtent(0, 17L), correlatedProducer(3, 0, 18L));
		SlotPlan outer = new UnionPlan(inner, classExtent(2, 19L));

		LmdbNativeKernelLowering.Lowered lowered = lowerDistinctCountingWithUnions(outer, 0);

		assertNotNull(lowered);
		assertEquals(-1, aggregateOutput(lowered).orderedDomain,
				"nesting must not erase the inner union's order break");
	}

	@Test
	void columnProducedByOnlyOneUnionBranchKeepsItsOrdering() {
		SlotPlan union = new UnionPlan(classExtent(0, 17L), classExtent(3, 18L));

		LmdbNativeKernelLowering.Lowered lowered = lowerDistinctCountingWithUnions(union, 0);

		assertNotNull(lowered);
		assertEquals(0, aggregateOutput(lowered).orderedDomain,
				"unbound rows from the other branch do not disturb the producing branch's order");
	}

	@Test
	void unionExpansionKeepsOrderingOfAnOuterColumn() {
		SlotPlan expansion = new UnionPlan(pattern(Term.slot(0), Term.slot(1)),
				pattern(Term.slot(0), Term.slot(2)));
		SlotPlan core = new JoinPlan(classExtent(0, 17L), expansion);

		LmdbNativeKernelLowering.Lowered lowered = lowerDistinctCountingWithUnions(core, 0);

		assertNotNull(lowered);
		assertEquals(0, aggregateOutput(lowered).orderedDomain,
				"all union rows for an outer value remain contiguous");
	}

	private static PatternPlan classExtent(int slot, long classId) {
		return new PatternPlan(Term.slot(slot), Term.constant(PRED), Term.constant(classId), Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, 512D);
	}

	private static SlotPlan correlatedProducer(int anchorSlot, int producedSlot, long classId) {
		PatternPlan extent = classExtent(anchorSlot, classId);
		PatternPlan correlated = new PatternPlan(Term.slot(anchorSlot), Term.constant(PRED + (1L << 7)),
				Term.slot(producedSlot), Term.unbound(), ContextConstraint.UNRESTRICTED, false, 512D);
		return new JoinPlan(extent, correlated);
	}

	private static LmdbNativeKernelIr.AggregateOutput aggregateOutput(
			LmdbNativeKernelLowering.Lowered lowered) {
		LmdbNativeKernelIr.Aggregate aggregate = (LmdbNativeKernelIr.Aggregate) lowered.kernel.terminal;
		return aggregate.outputs[0];
	}

	/**
	 * The correctness crux of union lowering: a variable both branches bind must land in ONE column, because a
	 * downstream node reads a single column. Allocating a second column for the second branch would leave the consumer
	 * reading a column only one branch ever wrote.
	 */
	@Test
	void bothUnionBranchesShareOneColumnForASharedVariable() {
		SlotPlan anchor = pattern(Term.slot(0), Term.slot(1));
		SlotPlan union = new UnionPlan(pattern(Term.slot(1), Term.slot(2)), pattern(Term.slot(1), Term.slot(2)));
		LmdbNativeKernelLowering.Lowered lowered = lowerCountingWithUnions(SlotPlan.join(anchor, union), 2);
		assertNotNull(lowered);
		// Slot 2 is bound by both branches, so exactly one column may be allocated for it.
		int slot2Columns = 0;
		for (int engineSlot : lowered.bindings.columnEngineSlots) {
			if (engineSlot == 2) {
				slot2Columns++;
			}
		}
		assertEquals(1, slot2Columns,
				"a variable bound by both branches needs exactly one column, got " + slot2Columns + "; columns="
						+ java.util.Arrays.toString(lowered.bindings.columnEngineSlots));
	}

	/**
	 * A branch-local filter must be lowered <em>inside</em> that branch: applying it after the union would filter the
	 * other branch's rows too. The shape key renders a union as {@code u{[branch][branch]}}, so an id filter belonging
	 * to one branch has to appear between those brackets rather than after the closing brace.
	 */
	@Test
	void aBranchLocalFilterIsLoweredInsideItsBranch() {
		SlotPlan anchor = pattern(Term.slot(0), Term.slot(1));
		// Left branch carries FILTER(?c != ?a); the right branch does not.
		MaskedFilter branchFilter = new MaskedFilter(
				new OrderedSlotCompareFilter(0, 2, Compare.CompareOp.NE, bindings -> true, true, true),
				1L | 1L << 2);
		SlotPlan left = new FilterPlan(pattern(Term.slot(1), Term.slot(2)), branchFilter.filter, branchFilter.mask);
		SlotPlan union = new UnionPlan(left, pattern(Term.slot(1), Term.slot(2)));
		LmdbNativeKernelLowering.Lowered lowered = lowerCountingWithUnions(SlotPlan.join(anchor, union), 2);
		assertNotNull(lowered, "a branch-local filter must lower inside the branch, not decline the union");
		String key = lowered.kernel.shapeKey();
		int unionStart = key.indexOf("u{");
		int unionEnd = key.indexOf("};", unionStart);
		assertTrue(unionStart >= 0 && unionEnd > unionStart, "expected a Union node in the key; key=" + key);
		String inside = key.substring(unionStart, unionEnd);
		assertTrue(inside.contains("ne(v0,v2);"),
				"the branch filter must sit inside the union braces; key=" + key);
	}

	/**
	 * A variable that is produced only by an earlier UNION branch is still a readable, nullable column in a later
	 * branch. A filter in that later branch must observe it as unbound (and therefore reject on SPARQL error), rather
	 * than making the whole generated plan decline because the lowering forgot the shared UNION column.
	 */
	@Test
	void laterUnionBranchCanFilterOnAnEarlierBranchNullableColumn() {
		SlotPlan first = pattern(Term.slot(0), Term.slot(1));
		MaskedFilter branchFilter = new MaskedFilter(
				new OrderedSlotCompareFilter(2, 0, Compare.CompareOp.EQ, bindings -> false, false, true),
				1L | 1L << 2);
		SlotPlan second = new FilterPlan(pattern(Term.slot(2), Term.slot(1)), branchFilter.filter,
				branchFilter.mask);

		LmdbNativeKernelLowering.Lowered lowered = lowerCountingWithUnions(new UnionPlan(first, second), 1);

		assertNotNull(lowered, "a later branch must be able to read an earlier branch's nullable UNION column");
		String key = lowered.kernel.shapeKey();
		int unionStart = key.indexOf("u{");
		int unionEnd = key.indexOf("};", unionStart);
		int filter = key.indexOf("fv", unionStart);
		assertTrue(unionStart >= 0 && filter > unionStart && filter < unionEnd,
				"the nullable comparison must remain inside its UNION branch; key=" + key);
	}

	/**
	 * A VALUES table joined on an outer variable is a membership filter, but its algebraic scope is still the branch
	 * that contains it. In particular, VALUES inside a UNION inside OPTIONAL must not become a filter over the
	 * OPTIONAL's left input.
	 */
	@Test
	void boundValuesMembershipStaysInsideItsOptionalUnionBranch() {
		SlotPlan anchor = pattern(Term.slot(0), Term.slot(1));
		ValuesPlan values = new ValuesPlan(new ValuesRow[] {
				new ValuesRow(new int[] { 0 }, new long[] { 100L }),
				new ValuesRow(new int[] { 0 }, new long[] { 200L }) });
		SlotPlan correlatedBranch = SlotPlan.join(values, pattern(Term.slot(0), Term.slot(2)));
		SlotPlan independentBranch = pattern(Term.slot(2), Term.slot(3));
		SlotPlan optional = new LeftJoinPlan(anchor, new UnionPlan(correlatedBranch, independentBranch));

		LmdbNativeKernelLowering.Lowered lowered = lowerCountingWithUnions(optional, 1);
		assertNotNull(lowered, "a bound VALUES table is a lowerable membership test");
		String key = lowered.kernel.shapeKey();
		int leftGroupStart = key.indexOf("lg[");
		int leftGroupEnd = key.indexOf("];", leftGroupStart);
		int membership = key.indexOf("in(v0");
		assertTrue(leftGroupStart >= 0 && leftGroupEnd > leftGroupStart, "expected an OPTIONAL left group; key=" + key);
		assertTrue(membership > leftGroupStart && membership < leftGroupEnd,
				"the VALUES membership test must stay inside the OPTIONAL arm; key=" + key);
	}

	/**
	 * A sticky (EXISTS-bearing) branch filter belongs inside the branch that defines it. Applying it after the UNION
	 * would incorrectly filter the other branch's rows.
	 */
	@Test
	void aStickyBranchFilterIsLoweredInsideItsBranch() {
		StubSource source = new StubSource();
		SlotPlan anchor = pattern(Term.slot(0), Term.slot(1));
		SlotPlan left = new FilterPlan(pattern(Term.slot(1), Term.slot(2)), existsWitness(source, 1), -1L);
		SlotPlan union = new UnionPlan(left, pattern(Term.slot(1), Term.slot(2)));
		LmdbNativeKernelLowering.Lowered lowered = lowerCountingWithUnions(SlotPlan.join(anchor, union), 2);
		assertNotNull(lowered, "the scope-aware witness belongs inside its UNION branch");
		String key = lowered.kernel.shapeKey();
		int unionStart = key.indexOf("u{");
		int unionEnd = key.indexOf("};", unionStart);
		int witness = key.indexOf("ex{", unionStart);
		assertTrue(unionStart >= 0 && witness > unionStart && witness < unionEnd,
				"the EXISTS witness must be contained by the UNION branch; key=" + key);
	}

	/**
	 * An empty UNION branch remains a real zero-row producer. It must lower explicitly rather than being dropped as an
	 * algebra simplification, because branch-local filters and wrappers still own the branch boundary.
	 */
	@Test
	void aggregateRungLowersAnEmptyUnionBranchAsAZeroRowProducer() {
		SlotPlan anchor = pattern(Term.slot(0), Term.slot(1));
		SlotPlan union = new UnionPlan(pattern(Term.slot(1), Term.slot(2)), EmptyPlan.INSTANCE);
		LmdbNativeKernelLowering.Lowered lowered = lowerCountingWithUnions(SlotPlan.join(anchor, union), 2);
		assertNotNull(lowered);
		assertTrue(lowered.kernel.shapeKey().contains("PR(p0->);"), lowered.kernel.shapeKey());
	}

	@Test
	void aggregateRungConsumesNativeSubqueriesThroughSemanticPlanRows() {
		NativeSubqueryPlan subquery = new NativeSubqueryPlan(
				bindings -> QueryEvaluationStep.EMPTY_ITERATION,
				new int[] { 2 }, new String[] { "c" }, new int[0], new String[0]);
		AggregateSpec[] count = { AggregateSpec.slot("count", 2, false, AggKind.COUNT) };
		String previousBridge = System.getProperty(LmdbNativeKernelLowering.PLAN_BRIDGE_PROPERTY);
		System.setProperty(LmdbNativeKernelLowering.PLAN_BRIDGE_PROPERTY, "false");
		try {
			LmdbNativeKernelLowering.Lowered root = LmdbNativeKernelLowering.lowerAggregate(subquery, freshRow(),
					new int[0], count, null);
			LmdbNativeKernelLowering.Lowered child = LmdbNativeKernelLowering.lowerAggregate(
					SlotPlan.join(pattern(Term.slot(0), Term.slot(1)), subquery), freshRow(), new int[0], count,
					null);

			assertNotNull(root, "a native subquery root must feed the native aggregate tier");
			assertNotNull(child, "a native subquery inside a join must feed the native aggregate tier");
			assertNull(root.planBridgeReason);
			assertNull(child.planBridgeReason);
			assertTrue(root.kernel.shapeKey().contains("PR(p0->"), root.kernel.shapeKey());
			assertTrue(child.kernel.shapeKey().contains("PR(p0->"), child.kernel.shapeKey());
		} finally {
			restoreProperty(LmdbNativeKernelLowering.PLAN_BRIDGE_PROPERTY, previousBridge);
		}
	}

	// ------------------------------------------------------------------
	// Sticky BooleanCombinationFilter decomposition (census 2026-07-25)
	// ------------------------------------------------------------------

	/** An EXISTS over {@code ?b PRED ?x}: a witness, which can never raise an error. */
	private static NativeBooleanFilter existsWitness(StubSource source, int subjectSlot) {
		return new StatementPatternExistsFilter(source, Term.slot(subjectSlot), Term.constant(PRED), Term.unbound(),
				Term.unbound(), ContextConstraint.UNRESTRICTED, false);
	}

	/** A plain comparison, which CAN raise a type error and therefore must not be negated by the kernel. */
	private static NativeBooleanFilter comparison() {
		return new OrderedSlotCompareFilter(0, 2, Compare.CompareOp.NE, bindings -> true, true, true);
	}

	private static LmdbNativeKernelLowering.Lowered lowerCountingWithSticky(StubSource source,
			NativeBooleanFilter sticky) {
		// A sticky filter (mask < 0) arrives as a FilterPlan wrapper around the producer, never flattened into the bag.
		SlotPlan core = new MultiJoinPlan(
				new SlotPlan[] { pattern(Term.slot(0), Term.slot(1)), pattern(Term.slot(1), Term.slot(2)) },
				new MaskedFilter[0]);
		SlotPlan wrapped = new FilterPlan(core, sticky, -1L);
		return LmdbNativeKernelLowering.lowerAggregate(wrapped,
				new RowState(source, LAYOUT, EmptyBindingSet.getInstance()), new int[0],
				new AggregateSpec[] { AggregateSpec.slot("count", 2, false, AggKind.COUNT) }, null);
	}

	/**
	 * {@code FILTER(EXISTS{...} && ?a != ?c)} splits into two sequential kernel filters, because sequential filters AND
	 * together. The non-witness conjunct needs no negation, so it can go through the ordinary id tier untouched.
	 */
	@Test
	void aggregateRungSplitsAConjunctionOfAWitnessAndAComparison() {
		StubSource source = new StubSource();
		NativeBooleanFilter conjunction = new BooleanCombinationFilter(existsWitness(source, 1), comparison(), true);
		LmdbNativeKernelLowering.Lowered lowered = lowerCountingWithSticky(source, conjunction);
		assertNotNull(lowered, "a conjunction of a witness and a comparison must split into two filters");
		String key = lowered.kernel.shapeKey();
		assertTrue(key.contains("ex{"), "the EXISTS conjunct must lower to a witness; key=" + key);
		assertTrue(key.contains("ne(v0,v2);"), "the comparison conjunct must lower to an id filter; key=" + key);
	}

	@Test
	void aggregateWitnessJoinEnumeratesSingleVariableValues() {
		StubSource source = new StubSource();
		ValuesPlan values = new ValuesPlan(new ValuesRow[] {
				new ValuesRow(new int[] { 3 }, new long[] { 100L }),
				new ValuesRow(new int[] { 3 }, new long[] { 200L }) });
		SlotPlan witness = new MultiJoinPlan(
				new SlotPlan[] { values, pattern(Term.slot(1), Term.slot(3)) },
				new MaskedFilter[0]);

		LmdbNativeKernelLowering.Lowered lowered = lowerCountingWithSticky(source, new ExistsFilter(witness));

		assertNotNull(lowered, "VALUES must be usable as a producer inside an EXISTS join");
		String key = lowered.kernel.shapeKey();
		assertTrue(key.contains("ex{ED(d0,k"), "the witness must enumerate its VALUES domain; key=" + key);
		assertTrue(key.contains("C(a2,v1,v"), "the graph pattern must probe the enumerated value; key=" + key);
		assertArrayEquals(new long[] { 100L, 200L }, lowered.bindings.keyDomains[0].literal);
	}

	@Test
	void aggregateWitnessLowersFourSlotFilterThroughExactResidual() {
		StubSource source = new StubSource();
		NativeBooleanFilter fourSlotFilter = new NativeBooleanFilter() {
			@Override
			public boolean accept(RowState row) {
				return row.view.size() >= 0;
			}

			@Override
			public long batchReadMask() {
				return 0b1111L;
			}
		};
		SlotPlan witness = new FilterPlan(pattern(Term.slot(1), Term.slot(3)), fourSlotFilter, -1L);

		LmdbNativeKernelLowering.Lowered lowered = lowerCountingWithSticky(source, new ExistsFilter(witness));

		assertNotNull(lowered, "a witness filter may read every live slot without leaving the kernel tier");
		assertTrue(lowered.kernel.shapeKey().contains("fr0("), lowered.kernel.shapeKey());
		assertEquals(1, lowered.bindings.kernelResiduals.length);
	}

	@Test
	void aggregateWitnessLowersAssuredAliasWithNullOnErrorContract() {
		StubSource source = new StubSource();
		SlotPlan witness = new ExtensionPlan(pattern(Term.slot(1), Term.slot(2)),
				new CopyBinding[] { CopyBinding.slot(3, 2) });
		SlotPlan producer = new FilterPlan(pattern(Term.slot(0), Term.slot(1)), new ExistsFilter(witness), -1L);

		LmdbNativeKernelLowering.Lowered lowered = LmdbNativeKernelLowering.lowerAggregate(producer,
				freshRow(source), new int[0],
				new AggregateSpec[] { AggregateSpec.slot("count", 1, false, AggKind.COUNT) }, null);

		assertNotNull(lowered, "an alias of a pattern-assured source cannot raise a BIND error");
		assertTrue(lowered.kernel.shapeKey().contains("ba(v"), lowered.kernel.shapeKey());
	}

	@Test
	void aggregateWitnessAcceptsDirectCorrelatedValuesWithDuplicates() {
		StubSource source = new StubSource();
		ValuesPlan values = new ValuesPlan(new ValuesRow[] {
				new ValuesRow(new int[] { 1 }, new long[] { 100L }),
				new ValuesRow(new int[] { 1 }, new long[] { 100L }),
				new ValuesRow(new int[] { 1 }, new long[] { 200L }) });

		LmdbNativeKernelLowering.Lowered lowered = lowerCountingWithSticky(source, new ExistsFilter(values));

		assertNotNull(lowered, "duplicate VALUES rows do not change existential membership");
		assertTrue(lowered.kernel.shapeKey().contains("ex{in(v1,"),
				"a correlated VALUES witness must lower to membership; key=" + lowered.kernel.shapeKey());
	}

	@Test
	void aggregateWitnessAcceptsACompleteMultiVariableValuesTable() {
		StubSource source = new StubSource();
		ValuesPlan values = new ValuesPlan(new ValuesRow[] {
				new ValuesRow(new int[] { 1, 3 }, new long[] { 100L, 300L }),
				new ValuesRow(new int[] { 1, 3 }, new long[] { 200L, 400L }) });

		LmdbNativeKernelLowering.Lowered lowered = lowerCountingWithSticky(source, new ExistsFilter(values));

		assertNotNull(lowered, "a complete VALUES table must lower as existential row alternatives");
		String key = lowered.kernel.shapeKey();
		assertTrue(key.contains("ex{u{["), "multiple VALUES rows must be witness alternatives; key=" + key);
		assertTrue(key.contains("eq(v1,c"), "the correlated column must be checked per row; key=" + key);
		assertTrue(key.contains("ba(c"), "the fresh column must be bound per row; key=" + key);
	}

	@Test
	void aggregateWitnessTreatsAnEmptyValuesTableAsNoWitness() {
		StubSource source = new StubSource();

		LmdbNativeKernelLowering.Lowered lowered = lowerCountingWithSticky(source,
				new ExistsFilter(new ValuesPlan(new ValuesRow[0])));

		assertNotNull(lowered, "an empty VALUES table has a deterministic false existential result");
		assertArrayEquals(new long[0], lowered.bindings.keyDomains[0].literal);
		assertTrue(lowered.kernel.shapeKey().contains("ex{ED(d0,k"),
				"enumerating an empty domain must produce no witness; key=" + lowered.kernel.shapeKey());
	}

	@Test
	void aggregateWitnessDeclinesPartialValuesRowsBeforeAJoin() {
		StubSource source = new StubSource();
		ValuesPlan values = new ValuesPlan(new ValuesRow[] {
				new ValuesRow(new int[] { 3 }, new long[] { 100L }),
				new ValuesRow(new int[0], new long[0]) });
		SlotPlan witness = new MultiJoinPlan(
				new SlotPlan[] { values, pattern(Term.slot(1), Term.slot(3)) },
				new MaskedFilter[0]);

		assertNull(lowerCountingWithSticky(source, new ExistsFilter(witness)),
				"UNDEF needs a row-specific unbound graph-pattern path, not a -1 adjacency probe");
	}

	/**
	 * {@code FILTER(!(EXISTS{..} || EXISTS{..}))} splits by De Morgan into two negated witnesses. Negation is exact
	 * here only because an EXISTS cannot raise an error.
	 */
	@Test
	void aggregateRungSplitsANegatedDisjunctionOfTwoWitnesses() {
		StubSource source = new StubSource();
		NativeBooleanFilter disjunction = new BooleanCombinationFilter(existsWitness(source, 1),
				existsWitness(source, 2), false);
		LmdbNativeKernelLowering.Lowered lowered = lowerCountingWithSticky(source,
				new NegatedNativeBooleanFilter(disjunction));
		assertNotNull(lowered, "NOT(A OR B) is NOT A AND NOT B, which splits into two negated witnesses");
		String key = lowered.kernel.shapeKey();
		assertEquals(2, key.split("nx\\{", -1).length - 1, "both witnesses must be negated; key=" + key);
	}

	/** A bare disjunction needs a real OR of witnesses, which the IR cannot express — it must decline. */
	@Test
	void aggregateRungDeclinesADisjunctionOfWitnesses() {
		StubSource source = new StubSource();
		assertNull(lowerCountingWithSticky(source,
				new BooleanCombinationFilter(existsWitness(source, 1), existsWitness(source, 2), false)),
				"A OR B cannot become two sequential filters, which would AND them");
	}

	/** {@code NOT(A AND B)} is {@code NOT A OR NOT B} — also a disjunction, so it must decline too. */
	@Test
	void aggregateRungDeclinesANegatedConjunction() {
		StubSource source = new StubSource();
		NativeBooleanFilter conjunction = new BooleanCombinationFilter(existsWitness(source, 1),
				existsWitness(source, 2), true);
		assertNull(lowerCountingWithSticky(source, new NegatedNativeBooleanFilter(conjunction)),
				"NOT(A AND B) is a disjunction of negations, not a conjunction");
	}

	/**
	 * The subtle one. {@code NOT(?a != ?c OR EXISTS{..})} would need the comparison negated, but
	 * {@code NegatedNativeBooleanFilter} is a plain {@code !accept} while a native filter already collapses a type
	 * error to false — so negating an erroring comparison yields <em>true</em> and keeps a row SPARQL drops. Only
	 * witnesses, which cannot error, may be negated, so this must decline.
	 */
	@Test
	void aggregateRungDeclinesNegatingAComparisonThatCanError() {
		StubSource source = new StubSource();
		NativeBooleanFilter disjunction = new BooleanCombinationFilter(comparison(), existsWitness(source, 1), false);
		assertNull(lowerCountingWithSticky(source, new NegatedNativeBooleanFilter(disjunction)),
				"negating a filter that can raise an error is not SPARQL negation");
	}

	/**
	 * {@code ExtensionCursor} turns a copy onto an already-bound slot into an equality test via {@code RowState.bind}.
	 * A fresh kernel column cannot express that, so such an extension must decline rather than overwrite the binding.
	 */
	@Test
	void aggregateRungDeclinesABindOntoAnAlreadyProducedSlot() {
		SlotPlan inner = new MultiJoinPlan(new SlotPlan[] { pattern(Term.slot(0), Term.slot(1)) },
				new MaskedFilter[0]);
		// Target slot 1 is already produced by the left pattern below, so the copy is an equality test, not a bind.
		SlotPlan core = SlotPlan.join(pattern(Term.slot(1), Term.slot(2)),
				new ExtensionPlan(inner, new CopyBinding[] { CopyBinding.slot(1, 2) }));
		assertNull(lowerCounting(core, 2), "a copy onto an already-bound slot is an equality test, not an alias");
	}

	// ------------------------------------------------------------------
	// Distinct dead-value demotion (keys-only EnumerateAdjKeys under DISTINCT)
	// ------------------------------------------------------------------

	private static final long PRED2 = 9L << 7 | 1L << 1;
	private static final long PRED3 = 11L << 7 | 1L << 1;

	private static MultiJoinPlan deadFanoutPlan() {
		// Derived order puts the cheap fan-out pattern first (estimate 5 vs 1000), so it lowers to the root
		// EnumerateAdjKeys with the dead ?c (slot 2) as its value column; ?b (slot 1) arrives via a probe.
		PatternPlan fanout = new PatternPlan(Term.slot(0), Term.constant(PRED2), Term.slot(2), Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, 5D);
		PatternPlan retainedLeg = new PatternPlan(Term.slot(0), Term.constant(PRED), Term.slot(1), Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, 1000D);
		return new MultiJoinPlan(new SlotPlan[] { fanout, retainedLeg }, new MaskedFilter[0]);
	}

	@Test
	void distinctSinkDemotesADeadValueRootToKeysOnly() {
		LmdbNativeKernelLowering.Lowered lowered = LmdbNativeKernelLowering.lowerDistinctRows(deadFanoutPlan(),
				freshRow(), null, false, new int[] { 1 });
		assertNotNull(lowered);
		String shape = lowered.kernel.shapeKey();
		assertTrue(lowered.kernel.pipeline.stream()
				.anyMatch(node -> node instanceof LmdbNativeKernelIr.EnumerateAdjKeys enumerate
						&& enumerate.valueCol < 0),
				shape);
		boolean witnessed = false;
		for (LmdbNativeKernelBindings.AdjacencyRequest request : lowered.bindings.adjacencies) {
			witnessed |= request.needsNonEmptyKeys;
		}
		assertTrue(witnessed, "the demoted enumeration must demand a non-empty-run view at bind time");
	}

	@Test
	void distinctSinkKeepsTheValueColumnWhenItIsARetainedKey() {
		LmdbNativeKernelLowering.Lowered lowered = LmdbNativeKernelLowering.lowerDistinctRows(deadFanoutPlan(),
				freshRow(), null, false, new int[] { 1, 2 });
		assertNotNull(lowered);
		String shape = lowered.kernel.shapeKey();
		assertFalse(shape.contains(",x-1)"), shape);
		for (LmdbNativeKernelBindings.AdjacencyRequest request : lowered.bindings.adjacencies) {
			assertFalse(request.needsNonEmptyKeys, shape);
		}
	}

	@Test
	void distinctSinkKeepsTheValueColumnWhenALaterPatternJoinsOnIt() {
		PatternPlan fanout = new PatternPlan(Term.slot(0), Term.constant(PRED2), Term.slot(2), Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, 5D);
		PatternPlan retainedLeg = new PatternPlan(Term.slot(0), Term.constant(PRED), Term.slot(1), Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, 1000D);
		PatternPlan joinsDeadSlot = new PatternPlan(Term.slot(2), Term.constant(PRED3), Term.slot(3), Term.unbound(),
				ContextConstraint.UNRESTRICTED, false, 2000D);
		MultiJoinPlan plan = new MultiJoinPlan(new SlotPlan[] { fanout, retainedLeg, joinsDeadSlot },
				new MaskedFilter[0]);
		LmdbNativeKernelLowering.Lowered lowered = LmdbNativeKernelLowering.lowerDistinctRows(plan, freshRow(), null,
				false, new int[] { 1 });
		assertNotNull(lowered);
		assertFalse(lowered.kernel.shapeKey().contains(",x-1)"), lowered.kernel.shapeKey());
	}

	@Test
	void distinctSinkDemotionHonoursItsKillSwitch() {
		String previous = System.getProperty(LmdbNativeKernelLowering.DISTINCT_DEAD_VALUE_DEMOTION_PROPERTY);
		System.setProperty(LmdbNativeKernelLowering.DISTINCT_DEAD_VALUE_DEMOTION_PROPERTY, "false");
		try {
			LmdbNativeKernelLowering.Lowered lowered = LmdbNativeKernelLowering.lowerDistinctRows(deadFanoutPlan(),
					freshRow(), null, false, new int[] { 1 });
			assertNotNull(lowered);
			assertFalse(lowered.kernel.shapeKey().contains(",x-1)"), lowered.kernel.shapeKey());
		} finally {
			if (previous == null) {
				System.clearProperty(LmdbNativeKernelLowering.DISTINCT_DEAD_VALUE_DEMOTION_PROPERTY);
			} else {
				System.setProperty(LmdbNativeKernelLowering.DISTINCT_DEAD_VALUE_DEMOTION_PROPERTY, previous);
			}
		}
	}

	@Test
	void pipelineTouchesColumnSeparatesReadsWritesAndPrivateColumns() {
		java.util.List<LmdbNativeKernelIr.Node> pipeline = java.util.List.of(
				new LmdbNativeKernelIr.EnumerateAdjKeys(0, 0, 1),
				new LmdbNativeKernelIr.Probe(1, LmdbNativeKernelIr.Operand.col(0), 2));
		assertFalse(LmdbNativeKernelIr.Kernel.pipelineTouchesColumn(pipeline, 0, 1),
				"a value column no other node reads or writes is private to its producer");
		java.util.List<LmdbNativeKernelIr.Node> joined = java.util.List.of(
				new LmdbNativeKernelIr.EnumerateAdjKeys(0, 0, 1),
				new LmdbNativeKernelIr.Probe(1, LmdbNativeKernelIr.Operand.col(1), 2));
		assertTrue(LmdbNativeKernelIr.Kernel.pipelineTouchesColumn(joined, 0, 1),
				"a probe keyed on the column is a read");
		java.util.List<LmdbNativeKernelIr.Node> rewritten = java.util.List.of(
				new LmdbNativeKernelIr.EnumerateAdjKeys(0, 0, 1),
				new LmdbNativeKernelIr.EnumerateAdjKeys(1, 1, 3));
		assertTrue(LmdbNativeKernelIr.Kernel.pipelineTouchesColumn(rewritten, 0, 1),
				"a column another node produces is a join coordinate, not a private value");
	}

	/** Minimal synthetic source: ids never resolve, no statements — the lowering must not need any of it. */
	/**
	 * A stub source that additionally reports a measured mean fan-out for exactly one (predicate, bySubject) pair, so
	 * the hash sink's derived-order chain comparison can price the probe chain from "real" statistics instead of the
	 * structural pseudo-cardinality fallback.
	 */
	private static final class FanOutStubSource extends StubSource {

		private final long predicate;
		private final boolean bySubject;
		private final double fanOut;

		FanOutStubSource(long predicate, boolean bySubject, double fanOut) {
			this.predicate = predicate;
			this.bySubject = bySubject;
			this.fanOut = fanOut;
		}

		@Override
		public java.util.OptionalDouble meanFanOut(long predicate, boolean bySubject) {
			return predicate == this.predicate && bySubject == this.bySubject ? java.util.OptionalDouble.of(fanOut)
					: java.util.OptionalDouble.empty();
		}
	}

	private static class StubSource implements NativeLmdbQuerySource {

		@Override
		public long idOf(Value value) throws QueryEvaluationException {
			return UNKNOWN_ID;
		}

		@Override
		public Value lazyValue(long id) throws QueryEvaluationException {
			return SimpleValueFactory.getInstance().createIRI("http://example.org/id/" + id);
		}

		@Override
		public Object idSpace() {
			return this;
		}

		@Override
		public RecordIterator statements(long subj, long pred, long obj, long context) throws IOException {
			throw new UnsupportedOperationException();
		}

		@Override
		public long count(long subj, long pred, long obj, long context) throws IOException {
			return 0L;
		}

		@Override
		public boolean has(long subj, long pred, long obj, long context) throws IOException {
			return false;
		}

		@Override
		public double estimate(long subj, long pred, long obj, long context) {
			return 0D;
		}

		@Override
		public boolean hasStatementsInSource() {
			return false;
		}
	}

	private static final class RouteTrackingSource extends StubSource {

		private int candidateRequests;
		private int forcedLmdbRequests;

		@Override
		public RecordIterator statements(long subj, long pred, long obj, long context) {
			candidateRequests++;
			return EmptyRecordIterator.INSTANCE;
		}

		@Override
		public RecordIterator lmdbStatements(long subj, long pred, long obj, long context,
				AdjacencyAccessObserver observer) {
			forcedLmdbRequests++;
			return EmptyRecordIterator.INSTANCE;
		}
	}
